% Automated Bioimage Analysis: Fluorescent Cell Morphology
% Author: Isaac Lo
% Project: 01-Cell-Morphology

clear; clc; close all;

%% 1. Load Data Exported from ImageJ (Case-Sensitive File Name)
data = readtable('Cell_Measurements.csv'); %[output:5747d934]

% Display the first few rows in the MATLAB command window
disp('Fluorescent cell measurement data successfully loaded:'); %[output:607013c8]
head(data); %[output:4c0e057c]

%% 2. Extract Key Morphometric Variables
cellArea = data.Area;
% ImageJ exports Circularity as 'Circ.' (imported as 'Circ_')
cellCircularity = data.Circ_; 

%% 3. Generate Publication-Quality Plots
figure('Name', 'Fluorescent Cell Morphometric Analysis', 'NumberTitle', 'off'); %[output:1742b90e]

% Subplot 1: Cell Area Distribution
subplot(1, 2, 1); %[output:1742b90e]
histogram(cellArea, 15, 'FaceColor', [0.17, 0.36, 0.56], 'EdgeColor', 'w'); %[output:1742b90e]
title('Fluorescent Cell Area Distribution', 'FontSize', 12); %[output:1742b90e]
xlabel('Area (\mum^2 or pixels)', 'FontSize', 10); %[output:1742b90e]
ylabel('Cell Count', 'FontSize', 10); %[output:1742b90e]
grid on; %[output:1742b90e]

% Subplot 2: Cell Circularity Distribution (1.0 = Perfect Circle)
subplot(1, 2, 2); %[output:1742b90e]
histogram(cellCircularity, 15, 'FaceColor', [0.85, 0.37, 0.01], 'EdgeColor', 'w'); %[output:1742b90e]
title('Cell Circularity (Morphology)', 'FontSize', 12); %[output:1742b90e]
xlabel('Circularity (4\pi \times Area / Perimeter^2)', 'FontSize', 10); %[output:1742b90e]
ylabel('Cell Count', 'FontSize', 10); %[output:1742b90e]
grid on; %[output:1742b90e]

%% 4. Save High-Resolution Figure for Portfolio
exportgraphics(gcf, 'matlab_cell_analysis.png', 'Resolution', 300); %[output:1742b90e]
disp('Analysis complete! Plot saved as matlab_cell_analysis.png'); %[output:447a508b]

